use App\Models\ParentModel;
use App\Models\ChildModel;
use Spatie\Tags\Tag;

// Function to consolidate all tags from child models and attach them to the parent model
function consolidateTagsToParent(ParentModel $parent)
{
    // Retrieve all child models associated with the parent
    $children = $parent->children; // Assuming 'children' is the relationship name

    // Initialize an empty collection to keep unique tags
    $allTags = collect();

    // Loop through each child model
    foreach ($children as $child) {
        // Retrieve tags for the current child model
        $childTags = $child->tags; // Assuming 'tags' is the relationship name for Spatie tags

        // Merge child tags into the allTags collection
        $allTags = $allTags->merge($childTags);
    }

    // Ensure all tags are unique
    $uniqueTags = $allTags->unique('name'); // Assuming 'name' is the column for tag uniqueness

    // Attach unique tags to the parent model
    $parent->syncTags($uniqueTags);
}

// Usage
$parent = ParentModel::find(1); // Replace 1 with the actual parent model ID
consolidateTagsToParent($parent);
```

