import UIKit

class IdleTimeTracker {
    private var idleTimer: Timer?
    private var idleTime: TimeInterval = 0
    private let idleInterval: TimeInterval = 1.0 // Check every second

    init() {
        NotificationCenter.default.addObserver(self, selector: #selector(resetIdleTimer), name: UIApplication.userDidTakeScreenshotNotification, object: nil)
        let gestureRecognizers: [UIGestureRecognizer] = [
            UITapGestureRecognizer(target: self, action: #selector(resetIdleTimer)),
            UIPanGestureRecognizer(target: self, action: #selector(resetIdleTimer)),
            UIPinchGestureRecognizer(target: self, action: #selector(resetIdleTimer)),
            UISwipeGestureRecognizer(target: self, action: #selector(resetIdleTimer))
        ]

        for recognizer in gestureRecognizers {
            UIApplication.shared.keyWindow?.addGestureRecognizer(recognizer)
        }

        startIdleTimer()
    }

    @objc private func resetIdleTimer() {
        idleTime = 0
    }

    private func startIdleTimer() {
        idleTimer = Timer.scheduledTimer(withTimeInterval: idleInterval, repeats: true) { [weak self] _ in
            self?.idleTime += self?.idleInterval ?? 0
            print("Idle time: \(self?.idleTime ?? 0) seconds")
        }
    }

    deinit {
        idleTimer?.invalidate()
        NotificationCenter.default.removeObserver(self)
    }
}

// Usage
let idleTimeTracker = IdleTimeTracker()
```

